quests[38144] = { id = 38144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demons Below", description = "Something, someone, intended us to never awaken. I sense their presence is still here in the barrow.\n\n<Koda takes a moment to stand.>\n\nMy body is weak from deep slumber.\n\nIf you would aid us, clear our barrow of any enemies.", progress = "This was no accident. Someone intended us to sleep forever.", completion = "Excellent. The chambers are clear. Very impressive, {class}.", objectives = "Kill 8 Darkfiend Intruders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38145] = { id = 38145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Dream", description = "Malfurion Stormrage... A name I have not heard in centuries.\n\nHe was teacher to many of us. If he seeks my audience, I cannot refuse.\n\nI will go to the Grove of Cenarius, but first, we must awaken the rest of my clan. They slumber with no way of waking.\n\nA mysterious force of great power is at work against us.\n\nI am still too weak from my hibernation. Please, stranger, go and free them from their dreams.", progress = "The Druids of the Claw must awaken. We are needed.", completion = "Well done, hero. With my brethren at my side, we will be ready to aid Malfurion.", objectives = "Awaken 8 Druids of the Claw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38146] = { id = 38146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chieftain's Beads", description = "The ceremonial beads, decorated with shells and feathers, are worn by the clan's chieftain.\n\nPerhaps Elder Sookh would be interested in seeing these.", completion = "Graw was the first to succumb to the madness, and the rest of the clan followed.\n\nWith these, I will take the reins as our clan's new chieftain.\n\nThank you, traveler. I will do my best to rebuild my clan.", objectives = "Speak to Elder Sookh at Smolderhide Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38147] = { id = 38147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entangled Dreams", description = "I sense powerful magic emanating from deep within the barrow.\n\nWhatever is down there weaves a powerful spell, entangling us within our dreams.\n\nI am still too weak, but your skills are quite impressive, hero. I can see why Malfurion puts his trust in you.\n\nGo and eliminate the source of this magic.", progress = "Someone entangled us within a sinister spell.", completion = "In my dreams, I saw the satyr's leader. His face was familiar, though I could not see it clearly.\n\nI pray to Elune that it is not too late. I will go to Malfurion at once.", objectives = "Kill Morphael.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38148] = { id = 38148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Grove", description = "Now that my clan is assembled, we shall return to the Grove of Cenarius.\n\nSpeak to Malfurion when you arrive. We will find out the cause of Cenarius' illness.", completion = "Wonderful. The Archdruids have already assembled.", objectives = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
