quests[38175] = { id = 38175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrap Meltdown", description = "We've had a breakthrough in melting down the scraps you've been collecting! If you can get me a small pile of 'em, we can get your troops something a bit more useful.", progress = "Do you have the scraps I've asked for?", completion = "Here ya are, commander. We've got to let the forges cool for a while, but we should be ready to process more scraps tomorrow.", objectives = "Kristen Stoneforge wants you to collect 25 Iron Horde Scraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38176] = { id = 38176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Stonefury Cliffs", description = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.\n\nShadow Hunter Rokhan has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38177] = { id = 38177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Magnarok", description = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north.\n\nIf we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38178] = { id = 38178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Iron Siegeworks", description = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.\n\nA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38179] = { id = 38179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Everbloom Wilds", description = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nRokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Botani forces in the Everbloom Wilds in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38180] = { id = 38180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Broken Precipice", description = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.\n\nMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the ogron forces at the Broken Precipice in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38181] = { id = 38181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Mok'gol Watchpost", description = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen.\n\nIf we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Warsong force at Mok'gol Watchpost in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38182] = { id = 38182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Darktide Roost", description = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38183] = { id = 38183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Socrethar's Rise", description = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley.\n\nSocrethar's disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38184] = { id = 38184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Lost Veil Anzu", description = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.\n\nRokhan has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38185] = { id = 38185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Pillars of Fate", description = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.\n\nRokhan is concerned at their proximity to key choke points leading into Shadowmoon Valley, and has put out a request that we thin their forces as soon as possible.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Shadowmoon forces at Pillars of Fate in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38186] = { id = 38186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Skettis", description = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.\n\nGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the arakkoa forces at Skettis in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38187] = { id = 38187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Shattrath Harbor", description = "Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar.\n\nThe Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Sargerei forces at Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38188] = { id = 38188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrap Meltdown", description = "We've figured out how to make those scraps in to something a bit more useful to your troops. Bring me a pile of them and I'll have our smiths process it for you.", progress = "Do you have the scraps I've asked for?", completion = "Very good, commander. This should prove useful to your troops.", objectives = "Grun'lek wants you to collect 25 Iron Horde Scraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38189] = { id = 38189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Stonefury Cliffs", description = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.\n\nBodrick Grey has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38190] = { id = 38190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Magnarok", description = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our outposts in the west. Most seem to originate from Magnarok in Frostfire Ridge.\n\nIf we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38191] = { id = 38191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Iron Siegeworks", description = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.\n\nA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38192] = { id = 38192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Everbloom Wilds", description = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nBodrick Grey has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the wilds of Gorgrond, giving us more room to maneuver around them.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the botani forces in the Everbloom Wilds of Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38193] = { id = 38193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Broken Precipice", description = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.\n\nMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the ogron forces at the Broken Precipice in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38194] = { id = 38194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Gorian Proving Grounds", description = "The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand.\n\nA decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.", objectives = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38195] = { id = 38195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Mok'gol Watchpost", description = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen.\n\nIf we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Warsong forces at Mok'gol Watchpost in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38196] = { id = 38196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Darktide Roost", description = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should still have time to get ahead of the problem.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38197] = { id = 38197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Socrethar's Rise", description = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley.\n\nSocrathar's disciples pose a threat to draenei and our garrison alike. We need to quell them at our soonest convenience.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38198] = { id = 38198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Lost Veil Anzu", description = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.\n\nBodrick Grey has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38199] = { id = 38199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Pillars of Fate", description = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.\n\nBodrick Grey is concerned at their proximity to the garrison, and has put out a request that we thin their forces as soon as possible.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Shadowmoon orcs at Pillars of Fate in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38200] = { id = 38200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Skettis", description = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.\n\nGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Adherents of Rukhmar at Skettis in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38201] = { id = 38201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on Shattrath Harbor", description = "Shattrath City is in the hands of Sargerei forces under the leadership of the traitor Exarch, Socrethar.\n\nMembers of the Sha'tari Defense have been requesting aid against the Shadow Council forces in the eastern portions of the city.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Sargerei forces at Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38202] = { id = 38202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missive: Assault on the Gorian Proving Grounds", description = "The ogres at the Gorian Proving Grounds be rousin' champions to turn against our forces in Nagrand.\n\nA decisive assault on their training grounds should prevent dem from musterin' the forces dey be needin' to stand against us, and will help remind them that we are not an enemy they want to be makin'.", objectives = "Assault the ogre forces at the Gorian Proving Grounds in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38203] = { id = 38203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challiane Vineyards", description = "Please, outsider, help me.\n\nMy recipe for Nightrose wine was to be the toast of Queen Azshara herself. But before I could make it, the vile vintners took it from me and locked me away.\n\nPlease, recover my recipe so that I might bring it to Lady Challiane and earn the queen's favor.", progress = "Have you found the pieces of the recipe?", completion = "Thank you, outsider! Thank you very much.\n\nYou have done more for me than my own people ever have.\n\nLady Challiane would never take the word of a lowly cellarman over her vintners.\n\nNow I can use this recipe to earn her favor, and then the favor of our beloved queen Azshara...", objectives = "Collect the 3 parts of the Nightrose recipe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38204] = { id = 38204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Gorian Proving Grounds", objectives = "Take out as many Shadowmoon orcs and their Void minions as you can.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38205] = { id = 38205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Gorian Proving Grounds", objectives = "Take out as many Shadowmoon orcs and their Void minions as you can.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38206] = { id = 38206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Rounds", description = "You must be wondering what all of this is about. Please, walk with me.\n\nI have some final preparations to make before we set sail, and I know that your presence will inspire the crew.", progress = "As soon as preparations are complete, we set out for Stormheim.", completion = "Are you with us?", objectives = "Follow Sky Admiral Rogers and prepare the Skyfire to set sail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38207] = { id = 38207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zeter'el" }
quests[38208] = { id = 38208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Weathered Axe" }
quests[38209] = { id = 38209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bramblefell" }
quests[38210] = { id = 38210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Trials", description = "<As the raven stares into your eyes, an odd voice fills your mind.>\n\nI know who you are, champion, and I know what you seek.\n\nCome to me, if you think yourself truly worthy.", completion = "I'm sure your head is filled with questions. Answers will come, in time.\n\nI am Havi, and my words are those of the Valarjar - the glorious keepers of the Halls of Valor. \n\nYou will need my help if it is the Aegis you seek. Oh yes, I know your goals outsider. As I know many things...", objectives = "Find Havi near Aggramar's Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38211] = { id = 38211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Felspark" }
quests[38212] = { id = 38212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brogozog" }
quests[38213] = { id = 38213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get a Clue", description = "Aktar mentioned that in the ruins he's seen Sethekk, ogres, even demons, but no sign of Iskar.\n\nWe're going to have to go in there if we're to find any clues and I'd prefer someone strong like yourself to lead the way.\n\nWell, what do you say?", progress = "The binding is dirty yet the pages are still in good condition. Upon the bottom of the binding is written \"Property of Iskar.\"", completion = "This tome looks like the one Iskar used to carry. What could have caused him to leave it?", objectives = "Search the Ruins of Kra'nak for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38214] = { id = 38214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "PH: Search the Ruins of Kra'nak for clues.", sourceObjective = "PH: Search the Ruins of Kra'nak", sourceObjectiveStatus = "unverified-source-field" }
quests[38215] = { id = 38215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 015 - Haustvald - ZTO" }
quests[38217] = { id = 38217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tide Behemoth" }
quests[38218] = { id = 38218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving The Lore", description = "<A cool breeze of thought and memory enters your mind as you touch the strangely glowing stone. Within an instant, the purpose of this stone has been made manifest.>\n\n<You realize that what you hold is a Stone of Remembrance; an object imbued with druidic knowledge and lore. The greedy Stoneblood harpies must have stolen these precious artifacts from the druids in Thas'talah. You decide to search for more of these missing stones and return them to the Archdruid of Lore.>", objectives = "Collect 12 Stones of Remembrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38219] = { id = 38219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending The Grove", description = "The harpies have had a presence in Val'Sharah for hundreds of years. They have never been much more than an occasional nuisance; thus we have tolerated their presence here within these woods.\n\nHowever, something has emboldened them... it feels as though the forest is weakening... they must sense it as well.\n\nThe opportunistic harpies have broken the peace and attacked us in a time of weakness.\n\nHelp us defend Thas'talah by slaying the invaders.", objectives = "Slay 12 Harpies involved in the attack on Thas'talah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38220] = { id = 38220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arauk Nashal 70:JP3 - Aggramar's Vault - Tracking Quest Cleared - Aggramar's Vault" }
quests[38222] = { id = 38222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "PH: Search the Ruins of Kra'nak for clues.", objectives = "PH: Search the Ruins of Kra'nak", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38223] = { id = 38223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Ascension", description = "You skim through the pages of the tome, most of them filled with notes on the nature of shadow and illusion. On the last pages you discover a journal:\n\nI continue to search for a cure to the curse of Sethe. If Terokk was restored I would not be in this situation. Damn Reshad!\n\nI was contacted by an orc that identified himself as Gul'dan. He has a cure for the curse! I must travel to Tanaan to search for the location of this \"cipher\" of his.\n\nTake this information to Reshad.", progress = "I wish it had not come to this...", completion = "Thank you, {name}.\n\nThis was no easy task and I am grateful once again for your assistance. Iskar's madness must be stopped.\n\nI trust that when the time comes you will be ready.", objectives = "Speak to Reshad in the Ruins of Kra'nak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38224] = { id = 38224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "PH: Search the Ruins of Kra'nak for clues.", objectives = "PH: Search the Ruins of Kra'nak", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38225] = { id = 38225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Witchmother", description = "The numberless years of my life have been dedicated to learning and perfecting the arts of healing and restoration.\n\nNothing in this world pains me more than taking a life, traveler.\n\nIt is with a heavy heart that I must commission the death of Magula, the leader of the harpies that threaten this grove.\n\nMay her death save the lives of more noble beings.", progress = "Has the terrible deed been accomplished, traveler?", completion = "May peace again fill our sacred grove.", objectives = "Slay Magula.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38227] = { id = 38227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A True Leader Inspires Others", description = "<Lord/Lady> {name}, for all of your mastery over the Light you cannot possibly be everywhere at once. As newly ordained Knights of the Silver Hand it is our duty to carry out your will and defend our world from the darkness.\n\nThere is an ancient tome within this sanctum by the armory that can serve as the means to disperse your will - direct our blades and we will carry out your command.", objectives = "Use the Command Table to send the Westfall Militia on a mission", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38231] = { id = 38231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Shrine Found" }
quests[38232] = { id = 38232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minion! Kill Them!", description = "Per your contract you will help me gather supplies for a perfectly harmless ritual.\n\nI need feathers, and horns. Lots of horns. See those shadowrunners, prowlers and heron over there in the Olivian Veil? They should have lots of both.\n\nOh! And I need olives. Lots of olives. One for each finger.\n\nMinion! Let's ride!", progress = "This land is ripe for the taking. Especially the olives. They are really ripe. And I love ripe olives.", completion = "Mmmm. Olives. I love these things. They are the only reason worth to come to this filthy world.", objectives = "Fulfill your part of the deal with Daglop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38234] = { id = 38234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Inscribed Ruin Found" }
quests[38235] = { id = 38235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solid as a Rock", description = "Cenarius requires me?\n\nI shall depart as soon as I am able, but I mustn't leave while my druids are in danger. A vile harpy coven has emerged and seeks to claim my grove as their own.\n\nThese vermin inflict a petrifying disease which, given time, will destroy the infected.\n\nWhile I wish for all of my followers to be cured, it is crucial that my elder disciples survive to protect the grove in my absence.\n\nIf you would assist us, find my disciples and rouse them from this terrible state.", progress = "Have you roused my disciples, traveler?", completion = "Your arrival was a blessing, friend.\n\nAnde'thoras-ethil.", objectives = "Rescue Marnor Lorleaf, Erwind Mistfen and Del'thanar Sagewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38236] = { id = 38236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Note Found" }
quests[38237] = { id = 38237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This IS In My Contract.", description = "To perform my ritual I need to use a special cave I have prepared at Gloombound Barrow.\n\nMeet me there and I will \"give\" you your reward. Hee hee.", completion = "Great deal right? You got to kill a demon, your fancy weapon got more fancy, and I get to be the master now. Everybody wins!", objectives = "Help Daglop complete his ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38238] = { id = 38238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beacher" }
quests[38239] = { id = 38239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Pile" }
quests[38240] = { id = 38240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Active" }
quests[38241] = { id = 38241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Magic", description = "Commander, I've heard reports of a strange stone found in the garrison mine.  The miners aren't sure what to make of it, but I have a feeling it could be useful.\n\nWhen you next find yourself at the mine, it may be worth investigating.  And if you don't mind, I would love to see the stone for myself.", progress = "Greetings sir.  Have you found the stone?", completion = "So it's as I imagined, a battle-stone!\n\nI've been able to collect similar stones here in Draenor, but never one this large!  A rare find indeed.", objectives = "Find the Strange Stone near your garrison mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38242] = { id = 38242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unearthed Magic", description = "Commander, da miners be findin' somethin' in our mine with strong mojo.  They don' be knowin' what ta do with it, so maybe you gonna go overe dere and check it out?\n\nIf you find it, bring it here so I can look closer at da magic.", progress = "Where be the stone?", completion = "Ah sure, I be findin' stones like this everywhere in Draenor, but never one dis big!", objectives = "Find the Strange Stone near your garrison mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38243] = { id = 38243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bit of Ore", progress = "Ore has been in high demand on my trading route, and I'm trying to restock my supply.  Would you be willing to trade?", completion = "It's been a pleasure trading with you." }
quests[38244] = { id = 38244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Ore" }
quests[38245] = { id = 38245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lots of Ore" }
quests[38246] = { id = 38246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemic Call", description = "I heard the others talking earlier. I may know the cause of their fear.\n\nThey say the Chieftain has a mysterious totem. It gives him power, and fearful visions.\n\nIf you destroy the totem, the madness will end.", completion = "Thank you, {name}! My nephew is returned to me.\n\nHe explains that the source of the madness comes from a powerful totem, deep in our village. \n\nIt makes sense, but who - or WHAT - gave us such a thing?\n\nI will share this knowledge with the druids at once.", objectives = "Destroy the Nightmare Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38250] = { id = 38250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Ruins of Kra'nak", description = "The Shadow Council have recruited the Sethekk and other power hungry Arakkoa to their service. Our allies in the Order of the Awakened have tracked them to a ruin in the west of Tanaan where the Shadow Council is instructing them in the use of fel magic.\n\nWe must strike at them before they can master their diabolic powers.", completion = "Welcome back, commander. Our scouts just returned with word of your success.\n\nWell done!", objectives = "Assault the Shadow Council forces at the Ruins of Kra'nak in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38251] = { id = 38251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 013 - Stone Trident" }
quests[38252] = { id = 38252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Ruins of Kra'nak", description = "The Shadow Council have recruited the Sethekk and other power hungry Arakkoa to their service. Our allies in the Order of the Awakened have tracked them to a ruin in the west of Tanaan where the Shadow Council is instructing them in the use of fel magic.\n\nWe must strike at them before they can master their diabolic powers.", progress = "How goes the attack, sir?", completion = "Welcome back, General. Our scouts just returned with word of your success.\n\nWell done!", objectives = "Assault the Shadow Council forces at the Ruins of Kra'nak in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38253] = { id = 38253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: War Council", description = "Your garrison is in an uproar. King Varian Wrynn himself is visiting your fortress to discuss your invasion plan for Tanaan Jungle.\n\nThe King is ready for you inside your town hall along with his full retinue. It would be wise not to keep him waiting...", completion = "<The King is studying maps of Tanaan Jungle and the surrounding area.>\n\n{name}! The Alliance owes you a great debt for establishing this garrison. Thanks to your bravery and commanding leadership, we've fought this war here on Draenor, instead of amongst our own homes and farmsteads.\n\nIt's time now to finish this. Are you ready for the final campaign?", objectives = "Speak with King Varian Wrynn inside the Town Hall of your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38254] = { id = 38254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Derailment", description = "Several orcs have spoken out since Gul'dan assumed control. Some were taken prisoner. Among them is an engineering prodigy: Solog Roark, \"The Iron Shipwright.\" He designed these docks as well as the great dreadnaughts of the orcish fleet. If my scouts are right, he's in that prison train as we speak... And he may be ready to defect!\n\nGather explosives and meet with Yrel at the train to the southeast!", progress = "Commander, it's you! Naielle promised she would send someone.", completion = "Roark is definitely in this prisoner train but it's locked tight. We'll have to - oh - you brought explosives? Naielle thinks of everything! Let's crack this car open and see if we can convince that engineer to defect...", objectives = "Collect Explosive Charges and a Detonator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38255] = { id = 38255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Train Gang", description = "These rangari will surround and cover the train car. Hit the detonator to blow open the doors.\n\nI will try to talk Roark into joining our cause. He's a genius around a drydock and our best hope for building a shipyard.\n\nIf it doesn't work, we must be prepared to kill him. The last thing we need is someone rebuilding another Iron Fleet...", completion = "Lower your weapon, stranger. Blackhand is dead and our new \"Warchief\" just signed my death sentence. It looks like I'm going mercenary.\n\nYou want to build a shipyard? Then you want me.", objectives = "Use the detonator to blow open the prison train, and convince Roark to join your cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38256] = { id = 38256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hook, Line, and... Sink Him!", description = "I can build you a shipyard. And not some wasteful piece of over-engineering like this place.\n\nBut I'm going to need my blueprints. My work was confiscated when Gul'dan turned this harbor over to Admiral Knar.\n\n<Roark spits.>\n\nGul'dan's green poison courses through Knar's veins. He's calling the shots from on high. We'll need to grapple up there to take him out.", progress = "I will rebuild.", completion = "<Solog Roark takes in the view of his harbor one final time.>\n\nWe built it all for nothing, {class}. Gul'dan will claim whatever your troops do not destroy.\n\nNext time, I will build something that will last.", objectives = "Use a Blackrock Grapple to reach Knar's bunker. Slay him to obtain Roark's Shipyard Blueprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38257] = { id = 38257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need a Shipwright", description = "The Iron Horde - or whatever Gul'dan is turning them into - has fallen back and fortified the entrance to Tanaan. A direct assault will take a heavy toll.\n\nHowever, the sea lanes are open. If we attack by both land and sea, Gul'dan's Horde will have no quarter. {name}, it's time to build a shipyard!\n\nWe'll need to source local resources. Travel to the Iron Docks, where a small Alliance reclamation force is already waiting. Gather what equipment you can, and find us a shipwright capable of building a fleet!", completion = "Commander! I was told to expect you. The situation here is chaos.\n\nMy Rangari have had this place under surveillance since your original assault. It's come back to life in recent weeks as the remnants of the Iron Horde flee to Tanaan under Gul'dan's orders.\n\nMy scouts have learned something that might interest you...", objectives = "Travel to the Iron Docks and speak with Exarch Naielle. Your Garrison Flight Master can provide transport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38258] = { id = 38258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Remains", description = "Nothing is left for me here. My old clanmates have turned into foes, and Gul'dan is desecrating what remains of my people.\n\nYou and your allies from Shattrath still have some fight left. If you pledge to depose Gul'dan, I will stand by your side. I will go to this garrison of yours and together we will build a shipyard that will rule the red seas of Draenor!\n\nLet your people know I am coming.", completion = "You found us a shipwright then? Good! Some of your followers are eager to take to the open seas.", objectives = "Report back to King Wrynn at the Town Hall in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38259] = { id = 38259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hands on Deck", description = "Let's put this \"Iron Shipwright\" of yours to work, commander. If we're to pull off your plan to assault Tanaan from both land and sea, we'll need to get some docks operational as soon as possible. Work with Roark and build the Alliance a shipyard!\n\nLast I saw, Roark was northwest of the garrison, near Eventide Landing.", progress = "I'll need building materials, commander. You can't build docks from mud.", completion = "<Roark scans the horizon.>\n\nYes, here. A good natural bay. The remains of that old warship can be gutted and turned into your first transport.\n\nI see you've gathered all the materials we need. Are you ready?", objectives = "Gather materials and construct a Level 1 Shipyard for your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38260] = { id = 38260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beachhead" }
