quests[38266] = { id = 38266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zulk" }
quests[38267] = { id = 38267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends Above", description = "Iskar disappeared and now the Shadow Council is at our throats. These can't be unrelated events. We need to go to the last place he was seen, the ruins of Kra'nak.\n\nI've asked a friend to set up a camp nearby. I say we head there to continue our search.", completion = "Ah, {name}. You're just in time.\n\nAktar says the Shadow Council are teaching the Sethekk their vile ways. There are even a group of High Arakkoa that have joined the Shadow Council's banner!\n\nI wonder how does Iskar factor into this?", objectives = "Meet with Reshad at Atkar's Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38268] = { id = 38268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkbane" }
quests[38269] = { id = 38269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends Above", description = "Iskar disappeared and now the Shadow Council is at our throats. These can't be unrelated events. We need to go to the last place he was seen, the ruins of Kra'nak.\n\nI've asked a friend to set up a camp nearby. I say we head there to continue our search.", completion = "Ah, {name}. You're just in time.\n\nAktar says the Shadow Council are teaching the Sethekk their vile ways. There are even a group of High Arakkoa that have joined the Shadow Council's banner!\n\nI wonder how does Iskar factor into this?", objectives = "Meet with Reshad at Atkar's Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38270] = { id = 38270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Killer", description = "With this map, you have pinpointed the origin of the attacks. It is time to see who or what is behind the attacks, and if they are a possible ally.", completion = "You... remember me? I came through the portal with you. I was called... Ariok. Before I became this.", objectives = "Locate the slayer of Bleeding Hollow near Zeth'Gol.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38271] = { id = 38271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Bloody Path", description = "The ones I kill... they speak of a cave. Sacred to the Bleeding Hollow. Kilrogg could be there - I am going.", completion = "Old earth... old blood. I smell Kilrogg. He has been here.", objectives = "Follow Ariok to the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38272] = { id = 38272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bleeding Hollow", description = "The cave pulls me. It keeps angry spirits near. Kilrogg has done magic here. You help me understand...", completion = "You step on hallowed ground, invader. Here the chieftains of the Bleeding Hollow have performed rituals to see the future.\n\nYou should die but there is much at stake...", objectives = "Reach the bottom of the Bleeding Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38273] = { id = 38273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Bleeding Hollow", description = "It is clear the cave is protected by powerful ghosts, ancestors of the Bleeding Hollow.\n\nWhatever is down there, it will be easier to deal with if many of the spirits were dealt with first.", objectives = "Slay 6 Enraged Blood Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38274] = { id = 38274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Kilrogg", description = "If you wish to know what Kilrogg and his new master intend, you will need his eye. After the ritual all chieftains place their eye under the protection of the ghosts of the Bleeding Hollow in the next chamber.\n\nGo and locate the Eye of Kilrogg in the vault. The other chieftains will not stand with us, and will fight you for it.\n\nThen place it on the ritual mark nearby to get your answers.", progress = "What have you learned?", completion = "Bah. Kilrogg not here. Only omens and warnings. That is your path {name}, mine is to destroy Kilrogg...", objectives = "Find the Eye of Kilrogg and perform the scrying ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38275] = { id = 38275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Return to Firelands 1 Mission Completed" }
