quests[38299] = { id = 38299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", progress = "Are we going to battle or what?", completion = "Not bad.  Not bad at all.  Stop by the next time I'm in the neighborhood, and I might have some new pets to check out.", objectives = "Defeat Erris the Collector in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38300] = { id = 38300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critters of Draenor", description = "I love collecting pets, and I've picked up a few unusual pets here in Draenor.  What would you say to a battle?  If you can defeat my humble team, I think we'll both learn a few new tricks.", progress = "Are we going to battle or what?", completion = "Not bad.  Not bad at all.  Stop by the next time I'm in the neighborhood, and I might have some new pets to check out.", objectives = "Defeat Kura Thunderhoof in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38304] = { id = 38304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'sharah", sourceObjective = "Speak to Malfurion Stormrage at Lor'lathil in Val'Sharah.", sourceObjectiveStatus = "unverified-source-field" }
quests[38305] = { id = 38305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarius, Keeper of the Grove", description = "Greetings, hero.\n\nWelcome to Val'sharah. It has been an age since I have set foot in these precious woods. Too long...\n\nOur work here is simple. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion.\n\nYou have many treacherous tasks in front of you. Consider your visit here a brief respite.\n\nCome, this will not take long.", objectives = "Speak to Malfurion Stormrage at Lorlathil in Val'Sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38306] = { id = 38306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Notebook", description = "This book has seen better days. Not much can be made out between the waterlogging and the apparent animal bites, but a few poor attempts at poetry center around the \"radiant glow\" of the Undercity and someone named Estelle Gendry.", completion = "<Estelle pages through the damaged tome and sighs wistfully.>\n\nOh dear, another paramour dead! Draenor has a terrible habit of eating my lovers alive.", objectives = "Return the notebook to Estelle Gendry in the Undercity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38307] = { id = 38307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Beckons", progress = "If only she weren't so specific about bringing you to her unharmed...", completion = "Satisfied?", objectives = "Read the Royal Summons and follow Nathanos Blightcaller through the portal to Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38308] = { id = 38308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes in the Overlook", description = "Alliance personnel from the Skyfire were spotted parachuting into Blackbeak Overlook.\n\nI was unable to confirm numbers or positions during my flyover, but I did see parachutes tangled in treetops and a LOT of ravenbears on the ground.\n\nIf anyone is up there, they must be laying low and keeping an eye on us.\n\nI have posted a rider at the top of the overlook to keep watch while I press forward into Stormheim.\n\n- Liza Cullen, Dread-Rider - 1st Wing", objectives = "Recover the SI:7 Intel from Spymaster Knockwhistle in Blackbeak Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38309] = { id = 38309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Content Perk: The Light Reveals" }
quests[38310] = { id = 38310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Content Perk: Righteous Strength" }
quests[38311] = { id = 38311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Content Perk: Call of the Highlord" }
quests[38312] = { id = 38312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grapple a Day", description = "So these trials are what will get us the Aegis, and the next one is on the top of that mountain? That may prove problematic.\n\nThe only way I see up the mountain is through that vrykul city, and the gates are shut tight. We should be able to grapple over, though. If you don't have a launcher, I managed to wrangle a spare from one of these vrykul.\n\nI'll scout ahead and see if I can find a good spot to get in.", completion = "That looks like it'll do the job nicely. \n\nLet's get in there before we're spotted.", objectives = "Pick up a Stormforged Grapple Launcher and meet Lorna Crowley outside the wall of Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38314] = { id = 38314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hidden Demon" }
quests[38316] = { id = 38316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 014 - Fel Collector" }
quests[38317] = { id = 38317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masters of Disguise", description = "<You scan over Knockwhistle's report.>\n\n\"My chute caught a piece of shrapnel. Made a rough landing in a ravenbear nest. Luckily, a bunch of eggs broke my fall.\n\nLost sight of Illandris and Shwayder. Both are masters of disguise, and I am confident they can remain undetected.\n\nWill continue to monitor the enemy's activity. Just need to clean all the yolk off my cloaking device. Hope the mother's not around...", progress = "We cannot speak freely - the Alliance have eyes and ears in the hills.", completion = "Finally, I can get back to the action!", objectives = "Slay Spymaster Illandris and Spymaster Shwayder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38318] = { id = 38318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Wings Required", description = "Now that you've got the launcher, we should be able to infiltrate the city. It looks like there's a good spot to grapple onto on the wall just past us. There's a vantage point on top of this ridge.\n\nOnce we're in, I'll try to slip past the guards and get a look at the mountain path. I'd appreciate if you could make some distractions for me. If all goes well, I'll meet up with you in the upper city.\n\nGood luck!", completion = "You should've seen the look on those vrykuls' faces when you came sailing over their wall! \n\nI could see that launcher coming in handy in a lot of places. You'd best hold on to it.", objectives = "Go to the top of the ridge and use the Stormforged Grapple Launcher to launch over the wall at Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38320] = { id = 38320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: The Blade of Kra'nak" }
quests[38321] = { id = 38321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackbeak Overlook" }
quests[38322] = { id = 38322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Grove", description = "Now that my grove is safe, I can turn my attention to the threat you speak of.\n\nTo hear of Cenarius' plight is disturbing indeed. Tell Malfurion that I shall meet him at the Grove.", completion = "Wonderful. The Archdruids have already assembled.", objectives = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38323] = { id = 38323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Grove", description = "Forgive me, {race}. Archdruid Moonclaw's fall is a terrible blow...\n\nMalfurion must be informed of what has transpired here. Inform him of Thaon's fate and of the return of Xavius.\n\nMake haste, friend. I fear this may be the greatest threat Val'sharah has ever faced.", completion = "Thaon will be dearly missed. We may not have always seen eye to eye, but he was a great druid and a true protector of the vale.\n\nXavius will pay for his death...", objectives = "Return to Malfurion Stormrage at the Grove of Cenarius in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38324] = { id = 38324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accessories of the Cursed", description = "Wait! Before ye go rushin' off, we might want to be gettin more than just seaweed. \n\nYe see, these vrykul also be carrying bones with them - worn all over like jewelry. If ye can get yer hands on some of the bones they got lyin around, it'll add to the disguise.\n\nSo what ye waitin for?", progress = "Make sure ye've got enough bones before we move on.", completion = "Ah yes, these will do. \n\nNow lets see what we can make to fool old Guarm, eh?", objectives = "Collect 8 Cursed Bones in Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38331] = { id = 38331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Havi's Test", description = "I could sense your power the moment you arrived in this land. You carry great purpose and a heavy task.\n\nKnow that the Aegis of Agrammar rests in the high halls of the All-Father. Only if you prove your valor, can you claim it against your foe.\n\nMany trials must you face for this, but first I must know your strength. My stew is incomplete, and my old bones couldn't carry the ingredients up the hill. \n\nYou look like you have a good arm. Will you help an old man finish his stew?", progress = "Smells good, doesn't it?", completion = "Hah, you throw like a shieldmaiden!\n\nWhat? That's a good thing! \n\nTry the stew, young champion, and savor the taste of a task well done.", objectives = "Toss ingredients from the Basket of Root Vegetables, Barrel of Crabs, and Hearty Vrykul Grains into Havi's Stewpot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38332] = { id = 38332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ranger Lord", description = "Good to see you survived the wreck. Nathanos made it as well, though his face is now even uglier than before.\n\nHe took a group of rangers north to look for Sylvanas - nobody has seen her since the battle.\n\nHe asked me to send you his way if you ever woke up.", completion = "<Nathanos narrows his eyes at the wreckage of Sylvanas' ship.>\n\nShe's out there... she has to be.", objectives = "Report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38333] = { id = 38333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Drake Wrestler" }
quests[38334] = { id = 38334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Jewel of Hellfire" }
quests[38337] = { id = 38337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Built to Scale", description = "The vrykul around here seem to use scales from these drakes to fashion their armor. \n\nIf you were able to gather enough material from the local drakes, you may be able to make something useful out of it.", progress = "Oh, what do you have there?", completion = "Good thinking gathering up these scales. \n\nIt should be simple enough to make a solid piece of armor from them.", objectives = "Collect Storm Drake Scales from the Stormwing drakes in Hrydhsal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38339] = { id = 38339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Kelp From My Foes", description = "I'm not sure what yer doin' here, but ye have my thanks. If ye want to get any further, though, ye'll need to get past that foul dog, Guarm.\n\nI've tried meself a few times, and I think I have a plan. If we can get some of the seaweed these kvaldir wear, we might be able to trick the mutt. Guarm's mean, ye see, but not too smart.\n\nWhat do ye say? Think ye can take on a few kvaldir?", progress = "Do ye have enough for a proper disguise?", completion = "Wait... ye killed how many kvaldir? Yer braver than I thought, outsider!\n\nI'm sure Helya will see that neither ye nor I belong here once we get past that dog of hers.", objectives = "Collect 20 pieces of seaweed from Kvaldir Mistcallers and Soulflayers in Helheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38341] = { id = 38341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halting the Nightmare", description = "The corruption of the vale is the work of satyrs.\n\nThe new power they wield is unlike any I've seen... it is dark, seething and terrible.\n\nNefarious demon totems help spread their taint upon the land.\n\nThe Nghtmare totems must be destroyed if we are to hold back the tide of corruption.", objectives = "Destroy 3 Nightmare Totems in the Moonclaw Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38342] = { id = 38342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Way", description = "Well, the bridge option is out. You still got that grapple launcher handy?\n\nIt looks like we can get across from the top of that tower over there. First thing's first, though, we'll need to deal with the big ugly sitting out front.\n\nYou take point.", progress = "Well, we made it this far...", completion = "Well, there's no stopping you, is there?", objectives = "Defeat Gunnlaug Scaleheart in Hrydshal, then climb to the top of the tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38343] = { id = 38343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Hel" }
quests[38344] = { id = 38344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Notebook", description = "This book has seen better days. Not much can be made out between the waterlogging and the apparent animal bites, but you can make out some sort of Ironforge-based drinking game scoring system involving a dwarf named Krom Stoutarm.", completion = "Oh now, this brings back some memories. Y'didn't look at the scores did you?\n\nThis belonged to ol' Nolan, may he rest in peace. Not a very good explorer, but a helluva drinker.", objectives = "Return the notebook to Krom Stoutarm in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38345] = { id = 38345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Numismatics", description = "I hate to be too cynical, but I don't think we're gonna find Nolan in one piece. Or in a lot of pieces.\n\nNolan was a nut for finding rare coins. He's been from one end of the world to the other finding them, and now he's gone and gotten himself killed looking for more mint condition Draenei coins. Tell you what - let me show you what these coins look like, you bring me a few more of them and I'll set up an exhibit in his honor.", progress = "How's the coin hunt going?", completion = "These are in great condition. Nolan would be green with envy.", objectives = "Bring Misprinted Draenic Coins to Krom Stoutarm in Ironforge. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38346] = { id = 38346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Numismatics", description = "I told him this was a fool's errand. Of course he would get himself killed over a handful of coins! Oh well, there are always new lovers to find.\n\nYou'll have to do in the mean time. And you are quite easy on the eyes, aren't you? Be a dear and find me more coins that look like this one? I need them for... research.", progress = "Well? Do you have the coins I asked you to find?", completion = "Excellent work. I knew you'd be useful, sugarplum.\n\nThere's something very unusual about these coins...", objectives = "Bring Misprinted Draenic Coins to Estelle Gendry in Undercity. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38347] = { id = 38347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealth by Seaweed", description = "There! The disguise be complete!\n\nDon't mind the smell, there. It's probably better that we smell like the kvaldir, as well. Though I have a feeling I'll be needin a priest to get this stench out once we're gone.", progress = "Gods, what is that stench?! \n\nThis disguise had better work!", completion = "That was a truly revolting, outsider. Even in death I've never witnessed such a disgusting smell.", objectives = "Use the Kvaldir Disguise to sneak by Guarm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38348] = { id = 38348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlock \"Silvermoon\"" }
quests[38351] = { id = 38351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portable Portals", description = "My assistants have figured out how to convert ogre waystones into useful items for our garrison. Speak with Varsha outside to start your first work order.", progress = "Did you find Varsha?", completion = "I see you found Varsha.  Now, keep him supplied with waystones and we will be well on our way to defeating the iron horde.", objectives = "Speak with Varsha outside the Spirit Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38352] = { id = 38352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kazrok" }
quests[38353] = { id = 38353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescued From Darkness", description = "Midnight Vale is home to a unique breed of Nightsaber known as the Vale Prowler. For centuries, our clan has lived in harmony with these great feline hunters.\n\nHowever, even as we speak satyrs are twisting and corrupting the vale into a place of death and nightmare. Even the forest itself lashes out in torment against the living, causing many of the forest creatures to flee the vale.\n\nI fear for the safety of the youngest nightsabers, who may yet be caught in the twisting chaos, unable to escape.", objectives = "Save 7 Prowler Cubs in The Midnight Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38354] = { id = 38354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portable Portals", description = "My assistants have figured out how to convert ogre waystones into useful items for our garrison.  Speak with Apprentice Var'nath outside to start your first work order.", completion = "I see you found Apprentice Var'nath.  Now, keep him supplied with waystones and we will be well on our way to defeating the iron horde.", objectives = "Speak with Apprentice Var'nath outside the Mage Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38355] = { id = 38355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 002 - Moonrest Shore - twh" }
quests[38356] = { id = 38356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing the Bass", description = "It's a bit quiet around here, in between the invasions and all.\n\nYou're in luck though, Commander! I can fix that, and boost morale among your troops all at the same time.\n\nAll you need to do is bring me a few items from around Draenor, and I'll fill your garrison with music. I'll even throw in a few music rolls from my own collection to get you started!\n\nWhat do you say?", progress = "Collect a Bass Blaster, Laz-Tron Disc Reader, Phonic Amplifier, S.P.R.K. Capacitor, and a Cord of Ancient Wood.", completion = "This is the best Draenor has to offer? Lucky for you I went to engineering school. One Tune-O-Tron 5000 coming up!" }
quests[38357] = { id = 38357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Side Effects May Include Mild Undeath", description = "Exposure to this particular \"byproduct\" is quite nasty.\n\nRapid cell degeneration quickly reduces the subject to a shambling husk incapable of any reason or thought beyond a violent, throbbing hatred for the warmth of life.\n\nAs you might imagine, the local fauna have been affected by the spill. Oh, and most of the crew as well...\n\nAnyway, good luck!", progress = "Come now, surely you don't intend to leave them in this state? Have you no compassion?\n\nHow about money - you like money, don't you?", completion = "The R.A.S. is nothing if not humane.", objectives = "Slay 10 Volatile Bears or Volatile Sailors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38358] = { id = 38358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pump it Up", description = "The Black Rose was a seafaring laboratory for the Royal Apothecary Society. Naturally, we had some volatile... \"byproducts\" onboard.\n\nRegrettably, one such substance was released during our skirmish with the Alliance gunship. As you can see, it is taking quite a toll on the coast.\n\nThe R.A.S. must remedy this situation before we press further inland.\n\nPlease take a containment unit and fill it with waste - for us to dispose of properly at a later time, of course.", progress = "There's still room in that containment unit.", completion = "Wonderful, just put that down anywhere. Careful not to spill it!\n\n<The apothecary snickers.>", objectives = "Fill the Containment Unit with Volatile Waste.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38359] = { id = 38359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 003 - Lorlathil - twh" }
quests[38360] = { id = 38360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Windrunner's Fate", description = "Finding Sylvanas is our only priority!\n\nWe will cover more ground if we split up. I will lead a team into the hills above the enemy's camp while you search the wreckage itself for any signs of the crew.\n\nOnce we've cleared the high ground, I will meet you at the far end of the beach.", completion = "So, she escaped after all...", objectives = "Search the wreckage of the Windrunner and the nearby coastline for signs of Sylvanas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38361] = { id = 38361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Blightcaller", description = "The Alliance dogs have bitten off more than they can chew. They have attacked the Banshee Queen, and invoked the wrath of her champion!\n\nLike my bow, my axes, and my hounds, you will be an agent of vengeance. Pile the bodies high, {class}, and know that I am doing the same. When next we meet, I expect to see blood upon your hands.", progress = "I have no use for soft buffoons! Begone if you haven't the stomach for vengeance!", completion = "They have only begun to pay for their insolence.", objectives = "Slay 15 7th Legion Paratroopers or Skyfire Gryphon-Riders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38362] = { id = 38362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Trophy", description = "It would seem Sylvanas does not wish to be followed - by us or anyone else.\n\nHer will is her own, it is not my place to question. Only to obey.\n\nIn the hills nearby, a gryphon master is preparing to take flight, no doubt to pursue our queen from the sky. My rangers are lying in wait - we need only to close our jaws around him.\n\nI will have his head when this is over.", progress = "Do you have his head?", completion = "Look carefully at this head, {name}. This is what comes to those who stand against the Forsaken.\n\nFor now, we should begin our search for the Aegis of Agrammar. I will send some scouts out to discern its location. You should start your search as well. \n\nWhat are you waiting for?", objectives = "Take the Head of Thane Wildsky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38363] = { id = 38363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 004 - Thas'talah Basin - twh" }
