quests[38374] = { id = 38374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault the Drekirjar" }
quests[38376] = { id = 38376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for the Highlord", description = "Tirion is fading away on that infernal shore... and the Ashbringer with him! We must not waste another moment.\n\nGive the word and we'll set off. We're ready when you are.", progress = "<Maxwell's eyes seem to struggle to meet your own.>", completion = "I owe you my life, {name}. We all do.", objectives = "Recover Tirion Fordring and the Ashbringer from the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38377] = { id = 38377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerald Queen", description = "{name}, you have returned. Good.\n\nI have counseled with the other archdruids and concluded that Cenarius' condition is merely a symptom of a much greater problem. Your experiences in Moonclaw Vale make that clear.\n\nWe need help.\n\nThere is one who can bring understanding to these events. With Thaon gone, we must ask that you aid us in reaching out to the Lady of Dreams.", completion = "Behold, Ysera, the Emerald Queen.", objectives = "Speak to Malfurion when ready.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38380] = { id = 38380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hivequeen Zsala" }
quests[38381] = { id = 38381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archdruid of Lore", description = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore.\n\nSeek him out and tell him that he is desperately needed here.", completion = "Welcome, traveler.", objectives = "Seek out Elothir in Thas'talah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38382] = { id = 38382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archdruid of the Vale", description = "Deep within our forest lies Moonclaw Vale.\n\nThere you will find a reclusive group of feral druids charged with the protection of Val'sharah from any that would seek to disrupt the balance of nature.\n\nThese druids are led by Thaon Moonclaw, the most fierce of the Archdruids.\n\nSeek him out. Let him know that Cenarius is in need of his aid.", completion = "Cenarius will have my aid once my grove has been made safe.", objectives = "Speak with Thaon Moonclaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38383] = { id = 38383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 019 - Helheim - ZTO" }
quests[38384] = { id = 38384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature's Call", description = "What vile power is this?!\n\nA curse with the strength to paralyze a demigod? Unimaginable!\n\nQuickly, {name}, you must gather the archdruids of the forest. With their help, we can summon Ysera. She will surely know what horror has overtaken my mentor.\n\nI will remain here and lend Cenarius what aid I can.\n\nReturn to Lorlathil and speak with Aranelle. She will know the archdruids' whereabouts.\n\nAnd please, friend, make haste...", completion = "Cenarius is in need? Lord of the Forest, we shall not fail you...", objectives = "Speak to Aranelle in Lorlathil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38386] = { id = 38386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 008 - Shadowfen - twh" }
