quests[38390] = { id = 38390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 012 - Grove of Cenarius - twh" }
quests[38391] = { id = 38391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 013 - Val'sharah - twh" }
quests[38392] = { id = 38392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 014 - Malorne's Refuge - twh" }
quests[38393] = { id = 38393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 015 - Malorne's Refuge - twh" }
quests[38394] = { id = 38394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Completionism", description = "Interesting - the coins you've brought back from your Garrison are slightly different than the ones Nolan collected in Outland. Y'see here, the markings along the edge? Very interesting stuff! This requires some more study an' that means more coins! Bring them to me and I'll see if I can scrounge up something for your trouble.", progress = "Aye? Y'got them coins yet?", completion = "Y'know, I think we might be on to somethin' big here.", objectives = "Bring Misprinted Draenic Coins to Krom Stoutarm in Ironforge. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38395] = { id = 38395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Completionism", description = "This is intolerable! The coins you brought me do not match the rest of the coins I already have! You aren't counterfeiting these are you? No? Hrumph. In that case I'm sorry we fought, dearie.\n\nThere's only one thing to do, buttercup: we need to complete the new set you've discovered. Bring me more misprinted coins!", progress = "I certainly hope these coins can complete this set so I can se-- er, so I can treasure them forever.", completion = "That wasn't so hard now was it, peaches?\n\n<Estelle holds the coins you brought up the the light and practically purrs.>\n\nYes yes, these are so very strange...", objectives = "Bring Misprinted Draenic Coins to Estelle Gendry in Undercity. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38396] = { id = 38396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Oddity", description = "I've been looking at some of the other coins in circulation plus the ones you've brought back. Some o' these are misprints... others are just plain wrong. Look 'ere. This one's got two heads. And the second one is smiling at me, where it wasn't before.\n\nThere's a bigger mystery in play here and these misprints are the key to figuring it out. I'm gonna need even more.", progress = "We're on the verge of a breakthrough here.", completion = "Good, good! I've got some awful suspicious suspicions about these here suspicious coins.", objectives = "Bring Misprinted Draenic Coins to Krom Stoutarm in Ironforge. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38397] = { id = 38397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Oddity", description = "Well sweet pea, I have good news and bad news for you. The good news is that you brought me enough coins to complete this new misprint set! The bad news is that not a single one of them has matched the original partial set.\n\nSee here - this coin has two heads. And the face on the reverse is grinning at me, where he was looking so dour only an hour ago. This one squints when I shine a light on it. Such a mystery! I must have more!", progress = "Has anyone told you today that you're beautiful? You are.", completion = "Honeybiscuit, when this is all over, you and I may be remembered as stumbling on a great paranormal discovery. Or I will at least.", objectives = "Bring Misprinted Draenic Coins to Estelle Gendry in Undercity. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38398] = { id = 38398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Helyra's Kraken" }
quests[38399] = { id = 38399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fencing the Rose", progress = "Looking to sell something?", completion = "Ah yes, an eternium rose.  I heard vendors suddenly stopped buying them... something about the resell value being too low.\n\nYou're in luck though, because I know a collector who still wants them.  In fact, I can take this one off your hands, but you'll have to come back tomorrow if you have another one to sell." }
quests[38400] = { id = 38400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Grand Warlock Nethekurse" }
quests[38402] = { id = 38402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Same, But Different", description = "I'm beginning to suspect these here coins are demonic. See? This one's got three eyes! This one always comes up tails. And over here - the ones you brought me earlier? They dissolved in holy water.\n\nI need to make absolutely sure this isn't a fluke - bring me a huge pile of coins to sort through so nobody can refute m'theory.", progress = "Incredible work. Yer gonna be a hero in the Explorer's League for sure.", completion = "Aye, I've been talkin' to the priests in the Mystic Ward and they confirmed my sucpicions. These 'misprinted' coins are all demonic in origin.\n\nYeh done a good deed takin' these out of circulation. Well done, {name}!", objectives = "Bring Misprinted Draenic Coins to Krom Stoutarm in Ironforge. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38404] = { id = 38404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Same, But Different", description = "A most intriguing theory has been put forth by an associate of mine that may explain what's wrong with these coins. We believe they might be demonic in origin. See? This one's got three eyes. And this one always comes up tails. And THIS one whispers to me at night - on now, don't be jealous sweetheart. You're still my favorite.\n\n...Provided you bring me more coins so I can confirm our theory. Run along!", progress = "You've done a most wonderful service for me. I won't forget you, sweetheart. At least not this week.", completion = "I am most gracious for your services. So many coins! Such a foul energy within them - do you feel it? Somebody was trying to corrupt the draenei from within.\n\nWell, don't you worry your pretty head any. My colleagues and I will take VERY good care of these. Thank you, lovely!", objectives = "Bring Misprinted Draenic Coins to Estelle Gendry in Undercity. Misprinted Draenic Coins can be found when completing your first Random Heroic Draenor dungeon each day.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38405] = { id = 38405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Weather the Storm", description = "I've been doing some nosing around, and it looks like these vrykul are making regular trips up the mountain themselves. They've got some specialized gear for it, so while we're here we should take some.\n\nI'd recommend finding some climbing treads to keep your grip on the slopes, as well as an oiled cloak to keep the rain out. Also, it looks like they carry enchanted lodestones, which seem to keep the lightning at bay. You should probably grab one of those, too.", progress = "Did you find everything?", completion = "Excellent. These should do well to protect you from the storm.", objectives = "Collect Climbing Treads, an Oiled Cloak, and an Enchanted Lodestone from Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38406] = { id = 38406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Scorpion Lunker", progress = "A monstrous sea scorpion?", completion = "This big fella must have been growing for years.  To be honest, it's so cute I'll probably just let it go.  Maybe you can catch it again one day!" }
quests[38407] = { id = 38407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bottled Up", description = "<You've found a message in a bottle on the corpse. It's a request for aid from someone named Okuna Longtusk. Okuna claims that he and his fellow shipmates are being held prisoner by sea giants.\n\nMaybe if you show the note to the ghost of Lady Irisse at the Crumbled Palace, she can point you in the right direction?>", completion = "You say you found this message in a bottle? How quaint.\n\nYes, I can point you in the right direction, but are you sure you want to take on the sea giant prince and his skrogs? Just to free a bunch of unwashed sailors?", objectives = "Take Okuna's Message to Lady Irisse.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38408] = { id = 38408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Goods", description = "New items are available from Sergeant Crowler.  I suggest you stop by and take a look at his new goods as soon as you can!", objectives = "Talk with Sergeant Crowler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38410] = { id = 38410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impalement Insurance", description = "I've got bad news. Those harpoon launchers up on the walls might cause us some problems. \n\nThey can't get at us down here, but once you start climbing that path, they're likely going to try to skewer you.\n\nIf you use that grapple launcher, you should be able to get on top of the walls and dismantle them. Watch out for the drakes, though!", completion = "Hah! I bet they never saw that coming!\n\nSeems like we've got no shortage of obstacles left, though.", objectives = "Grapple on top of the walls in Hrydshal and dismantle 7 Tideskorn Harpoon Launchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38411] = { id = 38411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Executor Riloth" }
quests[38412] = { id = 38412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Above the Winter Moonlight", description = "You should have a good vantage from this tower to grapple over to the mountain path. I can't help you once you're across, but you should be able to take it all the way up to the top. \n\nI hope you're able to find what you need from the dragons up there. Who knows what the God-King has done to them.", completion = "You are here for the trial? I'm afraid you might be too late.\n\nThis battle with these Felskorn has taken its toll. I am too weak to grant you the power you seek...\n\nBut perhaps you may be able to help...", objectives = "Grapple across from the tower and climb to the top of the mountain path.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38413] = { id = 38413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings of Liberty", description = "When the Felskorn assaulted the nest, the Thorignir fought bravely to save our brood. But their demonic allies proved too much, and many of us were captured.\n\nEven now they work to corrupt my brothers and sisters to turn them to their side. \n\nPlease, outsider, free them from this fate!", progress = "What news do you bring of my brothers and sisters?", completion = "I am truly indebted to you for this act. My siblings were not able to defend themselves against the Felskorn, and would have ended up their slaves. \n\nYou are a true friend of the Thorignir.", objectives = "Free Aleifir, Hrafsir, Erilar and Hridmogir in Thorim's Peak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38414] = { id = 38414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of a Dragon", description = "Through brute force and corruption, the God-King has taken the power you seek, but there may be hope for you and the Thorignir, {class}.\n\nWith the aid of fel powers such as I've never seen, the Felskorn are corrupting our young and seeking to enslave the Thorignir. Their leader, a demon of great power, has captured our mother and seeks to bend her to the God-King's will.\n\nFind her and free her from the demon's grasp - only then might the Thorignir regain our power and grant you aid.", progress = "Have you found our brood-mother?", completion = "I am relieved to hear that our mother is safe. \n\nI am sure she will wish to thank you herself.", objectives = "Find and rescue the mother of the Thorignir brood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38415] = { id = 38415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Onslaught at Auchindoun", description = "Your ally, Liadrin, has sent a missive requesting aid near Auchindoun. The Sargerei have made a new assault there and breached something important. It is no coincidence this happened after Gul'dan's ascendancy. We will watch the front here, commander.", completion = "I know the battle for Tanaan presses sorely on your forces commander. I am glad you came. The Sargerei and Gul'dan have the same masters, so this new attack likely affects you as well.", objectives = "Meet Liadrin at Auchindoun in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38416] = { id = 38416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Sargerei", description = "The Auchenai have been reporting for some time that something was... wrong... with Auchindoun. They were never able to find a reason. Suddenly the Sargerei attacked and blew open a hole into a subchamber.\n\nCorruption leaks from that hole, we need to stop it.", completion = "This is unfortunate. We cannot allow Gorefiend to aid Gul'dan's machinations. He must be slain once and for all.", objectives = "Locate and stop the source of corruption underneath Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38417] = { id = 38417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sargerei Menace", description = "An attack such as this was unexpected. They have deployed heavily and it will take me some time to marshal enough forces to root them out.\n\nAny Sargerei you can slay will make retaking this area much easier commander.", objectives = "Slay 12 Sargerei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38419] = { id = 38419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 018 - [The Greenway]" }
quests[38421] = { id = 38421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Onslaught at Auchindoun", description = "The Auchenai have sent me an urgent missive - Auchindoun is in jeopardy again! The Sargerei have renewed their assault  and breached the underhalls. I sense the hand of Gul'dan is behind this.\n\nGather your things and meet me in the Court of Souls West of Auchindoun at once!", completion = "I am glad you came at once. Something terrible is brewing beneath this holy place.", objectives = "Meet Yrel at Auchindoun in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38422] = { id = 38422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makrura Wave Event" }
quests[38423] = { id = 38423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Stormdrake Matriarch" }
quests[38424] = { id = 38424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thane's Mead Hall" }
quests[38425] = { id = 38425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Fel Thorignir" }
quests[38426] = { id = 38426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Tome of Secrets" }
quests[38427] = { id = 38427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Goods", description = "New items are available from Sergeant Grimjaw.  I suggest you stop by and take a look at his new goods as soon as you can!", objectives = "Talk with Sergeant Grimjaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38428] = { id = 38428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fel Puppy Of My Own", objectives = "<Tentatively, the pup licks your hand. After receiving a good scratch behind the ears, the pup barks and wags its tail.>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38430] = { id = 38430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Argosh the Destroyer" }
quests[38431] = { id = 38431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bladesquall" }
quests[38433] = { id = 38433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Jungle - Tracking Quest - Lion's Watch Built - JMC" }
quests[38434] = { id = 38434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashbringer", description = "The blade fell... during the battle... Broken Shore...\n\n<Tirion coughs up blood.>\n\nMy time... is short. You must go ahead... into the temple ruins...\n\nYou must... retrieve...\n\n...the Ashbringer.", objectives = "Retrieve the Ashbringer from the Lost Temple at the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38435] = { id = 38435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Invasion of Tanaan", description = "It is done! By your command we have built our first ship and can run our naval operations from here.\n\nNow that we have our transport, we can let Yrel and Archmage Khadgar know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.", completion = "The landing was easier than I expected but there is trouble ahead.", objectives = "Meet with Khadgar at your shipyard and then speak to Yrel to begin the invasion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38436] = { id = 38436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obstacle Course", description = "Our landing was unopposed. Why are these docks all but abandoned?\n\nThe rangari scouts up ahead report trouble. Bleeding Hollow scavengers are looting some abandoned buildings to the northwest, and an encampment of warlock cultists lurk near the Dark Portal. Let's find out what we can and meet up with our scouts.", completion = "Our forces can finish driving off the remaining lurkers. But there's another problem up ahead.", objectives = "Find any information on the forces deployed in the area and meet with the scouts afterwards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
